select ln.plan_id, ln.funding_plan_ln_id, ln.funding_plan_id, ln.exchange, (SELECT pq.currency FROM prj_quotation pq where pq.source_document_category = 'CON_CONTRACT' and pq.source_document_id = cc.contract_id) currency, (SELECT fc.currency_name FROM fnd_currency fc,prj_quotation pq where fc.currency_code = pq.currency and pq.source_document_category = 'CON_CONTRACT' and pq.source_document_id = cc.contract_id) currency_n, cc.contract_number, c.cashflow_id, c.contract_id, c.cf_item, c.cf_type, c.cf_direction, c.cf_status, c.times, (select h.description from hls_cashflow_item h where h.cf_item = c.cf_item)plan_id_n, c.due_date, c.due_amount, case when c.bp_id is null then ( select hbm.bp_id from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else c.bp_id end bp_id, case when c.bp_id is null then ( select hbm.bp_name from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = c.bp_id) end bp_id_n, hba.bank_account_id, case when hba.bank_account_name is null then ( select hbma.bank_account_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_name end bank_account_name, case when hba.bank_account_num is null then ( select hbma.bank_account_num from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_num end bank_account_num, case when hba.bank_full_name is null then ( select hbma.bank_full_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_full_name end bank_branch_name, c.payment_method, s.MEANING payment_method_n, c.FUNDING_PLAN_STATUS, nvl((select t.DEDUCT_AMOUNT from (select dt.funding_plan_ln_id,sum(dt.DEDUCT_AMOUNT) DEDUCT_AMOUNT from csh_payment_req_dt dt group by dt.funding_plan_ln_id) t where t.funding_plan_ln_id = ln.funding_plan_ln_id),0) DEDUCT_AMOUNT, (c.due_amount - nvl((select t.DEDUCT_AMOUNT from (select dt.funding_plan_ln_id,sum(dt.DEDUCT_AMOUNT) DEDUCT_AMOUNT from csh_payment_req_dt dt group by dt.funding_plan_ln_id) t where t.funding_plan_ln_id = ln.funding_plan_ln_id),0)) REMAINING_PAYABLE_AMOUNT from con_contract_cashflow c left join sys_code_value_b_v s on s.CODE = 'CSH.PAYMENT_METHOD' and c.payment_method = s.code_value left join hls_bp_master_bank_account hba on hba.bank_account_id = c.bank_account_id , con_contract cc, HLS_FUNDING_PLAN_LN ln
c.contract_id = cc.contract_id and c.cf_direction = 'OUTFLOW' and ln.plan_id = c.cashflow_id
and ln.funding_plan_id = #{fundingPlanId}
and ln.funding_plan_ln_id = #{fundingPlanLnId}

select ln.plan_id, ln.funding_plan_ln_id, ln.exchange, ln.currency, (SELECT currency_name FROM fnd_currency where currency_code = ln.currency) currency_n, cc.contract_number, c.cashflow_id, c.contract_id, c.cf_item, c.cf_type, c.cf_direction, c.cf_status, c.times, (select h.description from hls_cashflow_item h where h.cf_item = c.cf_item)plan_id_n, c.due_date, c.due_amount, case when c.bp_id is null then ( select hbm.bp_id from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else c.bp_id end bp_id, case when c.bp_id is null then ( select hbm.bp_name from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = c.bp_id) end bp_id_n, hba.bank_account_id, case when hba.bank_account_name is null then ( select hbma.bank_account_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_name end bank_account_name, case when hba.bank_account_num is null then ( select hbma.bank_account_num from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_num end bank_account_num, case when hba.bank_full_name is null then ( select hbma.bank_full_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_full_name end bank_branch_name, c.payment_method, s.MEANING payment_method_n, c.FUNDING_PLAN_STATUS, nvl((select t.DEDUCT_AMOUNT from (select dt.funding_plan_ln_id,sum(dt.DEDUCT_AMOUNT) DEDUCT_AMOUNT from csh_payment_req_dt dt group by dt.funding_plan_ln_id) t where t.funding_plan_ln_id = ln.funding_plan_ln_id),0) DEDUCT_AMOUNT, (c.due_amount - nvl((select t.DEDUCT_AMOUNT from (select dt.funding_plan_ln_id,sum(dt.DEDUCT_AMOUNT) DEDUCT_AMOUNT from csh_payment_req_dt dt group by dt.funding_plan_ln_id) t where t.funding_plan_ln_id = ln.funding_plan_ln_id),0)) REMAINING_PAYABLE_AMOUNT from con_contract_cashflow c left join sys_code_value_b_v s on s.CODE = 'CSH.PAYMENT_METHOD' and c.payment_method = s.code_value left join hls_bp_master_bank_account hba on hba.bank_account_id = c.bank_account_id , con_contract cc, HLS_FUNDING_PLAN_LN ln left join csh_payment_req_hd reqhd on reqhd.funding_plan_id = ln.funding_plan_id
c.contract_id = cc.contract_id and c.cf_direction = 'OUTFLOW' and ln.plan_id = c.cashflow_id
and reqhd.payment_req_Id=#{paymentReqId}
and ln.funding_plan_id = #{fundingPlanId}

select cprl.payment_req_ln_id,
cprl.payment_req_id, cprl.source_doc_category , -- cprl.source_doc_id, cprl.source_doc_line_id, cprl.amount , --cprl.payment_flag, cprl.payment_completed_date, ln.plan_id, ln.funding_plan_ln_id, ln.exchange, ln.currency, (SELECT currency_name FROM fnd_currency where currency_code = ln.currency) currency_n, cc.contract_number, c.cashflow_id, c.contract_id, c.cf_item, c.cf_type, c.cf_direction, c.cf_status, c.times, (select h.description from hls_cashflow_item h where h.cf_item = c.cf_item)plan_id_n, c.due_date, c.due_amount, case when c.bp_id is null then ( select hbm.bp_id from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else c.bp_id end bp_id, case when c.bp_id is null then ( select hbm.bp_name from prj_project_bp ppb,hls_bp_master hbm where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bp_id = hbm.bp_id and rownum=1 ) else (select hbm.bp_name from hls_bp_master hbm where hbm.bp_id = c.bp_id) end bp_id_n, hba.bank_account_id, case when hba.bank_account_name is null then ( select hbma.bank_account_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_name end bank_account_name, case when hba.bank_account_num is null then ( select hbma.bank_account_num from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_account_num end bank_account_num, case when hba.bank_full_name is null then ( select hbma.bank_full_name from prj_project_bp ppb,hls_bp_master_bank_account hbma where ppb.project_id = cc.project_id and ppb.bp_type = 'TENANT' and ppb.bank_account_id = hbma.bank_account_id and rownum=1 ) else hba.bank_full_name end bank_branch_name, c.payment_method, s.MEANING payment_method_n, c.FUNDING_PLAN_STATUS, nvl((SELECT t.DEDUCT_AMOUNT FROM (SELECT dt.funding_plan_ln_id, SUM(dt.DEDUCT_AMOUNT) AS DEDUCT_AMOUNT FROM csh_payment_req_dt dt GROUP BY dt.funding_plan_ln_id) t WHERE t.funding_plan_ln_id = ln.funding_plan_ln_id), 0) AS DEDUCT_AMOUNT, c.due_amount - nvl((SELECT t.DEDUCT_AMOUNT FROM (SELECT dt.funding_plan_ln_id, SUM(dt.DEDUCT_AMOUNT) AS DEDUCT_AMOUNT FROM csh_payment_req_dt dt GROUP BY dt.funding_plan_ln_id) t WHERE t.funding_plan_ln_id = ln.funding_plan_ln_id), 0) AS REMAINING_PAYABLE_AMOUNT
from con_contract_cashflow c left join sys_code_value_b_v s on s.CODE = 'CSH.PAYMENT_METHOD' and c.payment_method = s.code_value left join hls_bp_master_bank_account hba on hba.bank_account_id = c.bank_account_id LEFT JOIN csh_payment_req_ln cprl ON cprl.source_doc_line_id = c.cashflow_id , con_contract cc, HLS_FUNDING_PLAN_LN ln, csh_payment_req_hd reqhd
c.contract_id = cc.contract_id and c.cf_direction = 'OUTFLOW' and ln.plan_id = c.cashflow_id and reqhd.funding_plan_id = ln.funding_plan_id and cprl.payment_req_id = reqhd.payment_req_Id
and reqhd.payment_req_Id=#{paymentReqId}
and ln.funding_plan_id = #{fundingPlanId}
